import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { ICON_NAMES } from './icon-names'

/**
 * The committed sprite must match the committed icon list and lucide-static:
 * both are generated by scripts/build-icon-sprite.mjs, and this spec fails
 * when someone edits one without rerunning the script.
 */
const webRoot = process.cwd()
const sprite = readFileSync(join(webRoot, 'public/sprite/lucide.svg'), 'utf8')
const require = createRequire(join(webRoot, 'package.json'))

const symbols = new Map(
  [...sprite.matchAll(/<symbol id="([^"]+)"([^>]*)>([\s\S]*?)<\/symbol>/g)].map((match) => [
    match[1],
    { attributes: match[2], body: match[3] },
  ])
)

/** A lucide-static icon's shapes, normalised like the build script does. */
function lucideBody(name: string): string {
  const svg = readFileSync(require.resolve(`lucide-static/icons/${name}.svg`), 'utf8')
  const inner = /<svg[^>]*>([\s\S]*?)<\/svg>/.exec(svg)?.[1] ?? ''
  return inner
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .join('')
}

describe('icon sprite', () => {
  it('holds exactly the icons the app lists, alphabetically', () => {
    expect([...symbols.keys()]).toEqual([...ICON_NAMES])
    expect([...ICON_NAMES]).toEqual([...ICON_NAMES].sort())
  })

  it('every symbol uses the 1.75 px design stroke and inherits the text colour', () => {
    for (const [name, symbol] of symbols) {
      expect(symbol.attributes, name).toContain('stroke-width="1.75"')
      expect(symbol.attributes, name).toContain('stroke="currentColor"')
      expect(symbol.attributes, name).toContain('fill="none"')
      expect(symbol.attributes, name).toContain('viewBox="0 0 24 24"')
    }
  })

  it('every symbol carries the shapes of its lucide-static icon', () => {
    for (const name of ICON_NAMES) {
      expect(symbols.get(name)?.body, name).toBe(lucideBody(name))
    }
  })

  it('bakes no colour into the sprite', () => {
    expect(sprite).not.toMatch(/#[0-9a-fA-F]{3,8}\b/)
    expect(sprite).not.toMatch(/stroke="(?!currentColor)/)
  })
})
